(5994926, 875186, 22734, '<td valign="top">A great movie poster effect.</td>', 'A great movie poster effect.', '2010-05-06 23:00:32.000000', NULL, 0),
(5994927, 872610, 22734, '<td valign="top">Mind blowing!</td>', 'Mind blowing!', '2010-05-06 23:01:01.000000', NULL, 0),
(5994929, 873346, 22734, '<td valign="top">While not meeting the challenge head on, a compelling image nonetheless! Good job.</td>', 'While not meeting the challenge head on, a compelling image nonetheless! Good job.', '2010-05-06 23:02:40.000000', NULL, 0),
(5994932, 875047, 22734, '<td valign="top">Good impact.</td>', 'Good impact.', '2010-05-06 23:03:38.000000', NULL, 0),
(5994937, 875208, 22734, '<td valign="top">A very good study in general. The eyes do become lost for a moment with the dog, and interrupts the otherwise nice flow of the composition. I love the b/w treatment.</td>', 'A very good study in general. The eyes do become lost for a moment with the dog, and interrupts the otherwise nice flow of the composition. I love the b/w treatment.', '2010-05-06 23:09:29.000000', NULL, 0),
(5994940, 874306, 22734, '<td valign="top">This image exudes a lot of charm. Nice work.</td>', 'This image exudes a lot of charm. Nice work.', '2010-05-06 23:10:37.000000', NULL, 0),
(5994944, 874443, 22734, '<td valign="top">A very cool effect. Of course, a few more takes may have yielded one where the entire fingers were preserved, yet, I understand the process involved of which time is the worst. These images require so much work and patience, but hey, you did good.</td>', 'A very cool effect. Of course, a few more takes may have yielded one where the entire fingers were preserved, yet, I understand the process involved of which time is the worst. These images require so much work and patience, but hey, you did good.', '2010-05-06 23:14:56.000000', NULL, 0),
(5994945, 874718, 22734, '<td valign="top">At least this image gives you experience exposing fire. Wild thing those flames.</td>', 'At least this image gives you experience exposing fire. Wild thing those flames.', '2010-05-06 23:17:57.000000', NULL, 0),
(5994962, 874861, 22734, '<td valign="top">My hat goes off to you. This is such a major task and you 95% executed it. Very difficult, mainly on alignment and vertical division of line of demarcation. I do not think that I have ever seen a first challenge entry with this complexity. I have found out that these attempts must score above 99.5 in technique to yield a good score. In short, do not be discouraged and rest assured that you have what it takes to introduce some winners in the future. Kudos!</td>', 'My hat goes off to you. This is such a major task and you 95% executed it. Very difficult, mainly on alignment and vertical division of line of demarcation. I do not think that I have ever seen a first challenge entry with this complexity. I have found out that these attempts must score above 99.5 in technique to yield a good score. In short, do not be discouraged and rest assured that you have what it takes to introduce some winners in the future. Kudos!', '2010-05-06 23:29:05.000000', NULL, 0),
(5994968, 874499, 22734, '<td valign="top">A very nice image. When I look at it my mind envisions a black vase to let the egg speak all the way down, but of course the effect would be different. Nevertheless, it is pleasing to look at.</td>', 'A very nice image. When I look at it my mind envisions a black vase to let the egg speak all the way down, but of course the effect would be different. Nevertheless, it is pleasing to look at.', '2010-05-06 23:33:41.000000', NULL, 0),
(5994971, 874537, 22734, '<td valign="top">Strange you wrote that about the curtains. These shots become so much easier to control with an independent light source. Yet, you did pretty good.</td>', 'Strange you wrote that about the curtains. These shots become so much easier to control with an independent light source. Yet, you did pretty good.', '2010-05-06 23:36:12.000000', NULL, 0),
(5994976, 873576, 22734, '<td valign="top">A nice effect. Despite minor exposure distractions, the image is alluring. The best way to approach these type of images is to shoot a couple, study and tighten up on the detail. Consider your feet wet for a future challenge.</td>', 'A nice effect. Despite minor exposure distractions, the image is alluring. The best way to approach these type of images is to shoot a couple, study and tighten up on the detail. Consider your feet wet for a future challenge.', '2010-05-06 23:42:36.000000', NULL, 0),
(5994979, 874599, 22734, '<td valign="top">I would have a place a velvet cloth atop the table to enhance this image even more. Regardless, you did very well.</td>', 'I would have a place a velvet cloth atop the table to enhance this image even more. Regardless, you did very well.', '2010-05-06 23:44:47.000000', NULL, 0),
(5994982, 874366, 22734, '<td valign="top">Great execution and good concept.</td>', 'Great execution and good concept.', '2010-05-06 23:46:17.000000', NULL, 0),
(5994986, 873558, 22734, '<td valign="top">Cool....................</td>', 'Cool....................', '2010-05-06 23:46:58.000000', NULL, 0),
