(5995109, 874994, 22734, '<td valign="top">Okay, so you got carried away and over did it. The effect and feel of the image are good.</td>', 'Okay, so you got carried away and over did it. The effect and feel of the image are good.', '2010-05-07 00:33:51.000000', NULL, 0),
(5995110, 874972, 22734, '<td valign="top">This is a beautiful image in itself and a probable higher placing one in another challenge. I love it.</td>', 'This is a beautiful image in itself and a probable higher placing one in another challenge. I love it.', '2010-05-07 00:36:01.000000', NULL, 0),
