(5995120, 875168, 22734, '<td valign="top">Great execution, but the artwork overshadowed the initial challenge. A good image.</td>', 'Great execution, but the artwork overshadowed the initial challenge. A good image.', '2010-05-07 00:47:06.000000', NULL, 0),
