INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5996527, 874590, 22734, '<td valign="top">A very good concept which should have been further explored. There is great potential here.</td>', 'A very good concept which should have been further explored. There is great potential here.', '2010-05-07 23:48:22.000000', NULL, 0),
(5996528, 875137, 22734, '<td valign="top">Soothing....</td>', 'Soothing....', '2010-05-07 23:49:01.000000', NULL, 0),
(5996530, 874751, 22734, '<td valign="top">Great fast change artist!</td>', 'Great fast change artist!', '2010-05-07 23:50:12.000000', NULL, 0),
(5996533, 874602, 22734, '<td valign="top">This is a great wall hanger. It will certainly enhance a room. The coloration is charming.</td>', 'This is a great wall hanger. It will certainly enhance a room. The coloration is charming.', '2010-05-07 23:51:50.000000', NULL, 0),
(5996537, 874620, 22734, '<td valign="top">A great change of pace. Very funny.</td>', 'A great change of pace. Very funny.', '2010-05-07 23:53:14.000000', NULL, 0),
(5996549, 875093, 22734, '<td valign="top">Very interesting and you get credit for following your idea. One simply does not know where some will lead to. Keep batting!</td>', 'Very interesting and you get credit for following your idea. One simply does not know where some will lead to. Keep batting!', '2010-05-07 23:56:27.000000', NULL, 0),
(5996556, 874495, 22734, '<td valign="top">Very nice colors and good framing.</td>', 'Very nice colors and good framing.', '2010-05-07 23:58:29.000000', NULL, 0),
(5996562, 874856, 22734, '<td valign="top">A good practice shot for future themes.</td>', 'A good practice shot for future themes.', '2010-05-08 00:00:11.000000', NULL, 0),
