(5996568, 875024, 22734, '<td valign="top">Highly interesting but further development would have help. Consider it a stepping stone into another future study.</td>', 'Highly interesting but further development would have help. Consider it a stepping stone into another future study.', '2010-05-08 00:04:35.000000', NULL, 0),
(5996572, 874993, 22734, '<td valign="top">This is quite an artistic shot. I love it.</td>', 'This is quite an artistic shot. I love it.', '2010-05-08 00:05:41.000000', NULL, 0),
(5996575, 874971, 22734, '<td valign="top">Now, here you have a highly imaginative concept. I would have examined it deeper and played variation upon variation to say exactly what you meant. Regardless, you get good credit. There are many more ideas where this came from for future entries.</td>', 'Now, here you have a highly imaginative concept. I would have examined it deeper and played variation upon variation to say exactly what you meant. Regardless, you get good credit. There are many more ideas where this came from for future entries.', '2010-05-08 00:08:40.000000', NULL, 0),
(5996579, 871857, 22734, '<td valign="top">Love the gushing laughter versus the pensive state.</td>', 'Love the gushing laughter versus the pensive state.', '2010-05-08 00:10:53.000000', NULL, 0),
(5996582, 873055, 22734, '<td valign="top">The subtle monochrome charms any viewer.</td>', 'The subtle monochrome charms any viewer.', '2010-05-08 00:11:52.000000', NULL, 0),
(5996607, 874793, 42013, '<td valign="top">Excellent Jason!! really great positioning!</td>', 'Excellent Jason!! really great positioning!', '2010-05-08 00:33:20.000000', NULL, 0),
