(5996988, 875184, 101702, '<td valign="top">As mentioned during the challenge, I was sure this was the blue... miles ahead of the others. Tactical voting???<br/> <br/>No way this deserved any 1''s</td>', 'As mentioned during the challenge, I was sure this was the blue... miles ahead of the others. Tactical voting??? No way this deserved any 1''s', '2010-05-08 08:45:15.000000', NULL, 0),
(5997008, 875225, 90495, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by graphicfunk:</b></div><hr/><i> That''s quite a punch you deliver. </i></td></tr></table> <br/> <br/>That''s my oldest son. :)</td>', 'Originally posted by graphicfunk: That''s quite a punch you deliver.   That''s my oldest son. :)', '2010-05-08 09:18:24.000000', NULL, 0),
(5997682, 873137, 22734, '<td valign="top">Eh, so what?, the pensive look is great!</td>', 'Eh, so what?, the pensive look is great!', '2010-05-08 19:56:41.000000', NULL, 0),
(5997683, 875215, 22734, '<td valign="top">Hey, that''s pretty good acting.</td>', 'Hey, that''s pretty good acting.', '2010-05-08 19:57:54.000000', NULL, 0),
(5997684, 875016, 22734, '<td valign="top">Well, at least this effort is a great learning experience. You certainly have an understanding of the elements. The future will aid you in better blending.</td>', 'Well, at least this effort is a great learning experience. You certainly have an understanding of the elements. The future will aid you in better blending.', '2010-05-08 20:00:00.000000', NULL, 0),
(5997685, 875120, 22734, '<td valign="top">All that change while the sensor fried! The gear does add hilarious interest.</td>', 'All that change while the sensor fried! The gear does add hilarious interest.', '2010-05-08 20:01:12.000000', NULL, 0),
(5997687, 874663, 22734, '<td valign="top">Well, at least you understand the principles involved. Many more ideas will come your way.</td>', 'Well, at least you understand the principles involved. Many more ideas will come your way.', '2010-05-08 20:03:47.000000', NULL, 0),
(5997690, 874865, 22734, '<td valign="top">What a cute child. I would have done one shot of him on the bike and the other standing right in front, as if ordering it to stop.</td>', 'What a cute child. I would have done one shot of him on the bike and the other standing right in front, as if ordering it to stop.', '2010-05-08 20:06:38.000000', NULL, 0),
(5997691, 874185, 22734, '<td valign="top">Pop Art. Pretty colors.</td>', 'Pop Art. Pretty colors.', '2010-05-08 20:07:11.000000', NULL, 0),
(5997692, 874902, 22734, '<td valign="top">This may have missed the mark of the challenge, but that color background is a winner.</td>', 'This may have missed the mark of the challenge, but that color background is a winner.', '2010-05-08 20:08:07.000000', NULL, 0),
(5997697, 874711, 22734, '<td valign="top">Ah, this is very nice but you have saved it for another challenge. Many at DPC are sticklers to the theme of the challenge. Nice work and the concept along with the execution is great.</td>', 'Ah, this is very nice but you have saved it for another challenge. Many at DPC are sticklers to the theme of the challenge. Nice work and the concept along with the execution is great.', '2010-05-08 20:10:17.000000', NULL, 0),
