(5997703, 874359, 22734, '<td valign="top">You got the mechanics down well, you just need a more striking idea to hit pay dirt.</td>', 'You got the mechanics down well, you just need a more striking idea to hit pay dirt.', '2010-05-08 20:12:07.000000', NULL, 0),
(5997710, 874459, 22734, '<td valign="top">The double exposure is good. One way to have helped the image is to have covered the background with black material for the face shot, remove it and shoot the second. Now, a neutral wall would have made the image better. Truly, a cute face.</td>', 'The double exposure is good. One way to have helped the image is to have covered the background with black material for the face shot, remove it and shoot the second. Now, a neutral wall would have made the image better. Truly, a cute face.', '2010-05-08 20:17:39.000000', NULL, 0),
(5997711, 874924, 22734, '<td valign="top">Keep experimenting and a winner idea will find you. This effort is good training.</td>', 'Keep experimenting and a winner idea will find you. This effort is good training.', '2010-05-08 20:20:59.000000', NULL, 0),
(5997712, 872096, 22734, '<td valign="top">Highly interesting, like numbers out of the night.</td>', 'Highly interesting, like numbers out of the night.', '2010-05-08 20:22:05.000000', NULL, 0),
